import Foundation
import NIO
import NIOHTTP1

// CI/CD Pipeline Controller for Kubernetes Pod Lifecycle Management
// Handles build artifact promotion and deployment state transitions

final class PipelineController {
    private let eventLoop: EventLoop
    private var deploymentState: DeploymentState = .idle
    private var artifactRegistry: [String: ArtifactMetadata] = [:]
    private var pendingCallbacks: [(String, (Result<Void, Error>) -> Void)] = []
    private let kubeClient: KubernetesClient
    private var stateVersion: UInt64 = 0
    private var isProcessingCallbacks: Bool = false

    enum DeploymentState: Equatable {
        case idle
        case promoting(artifactId: String)
        case deploying(artifactId: String)
        case rollingBack(fromVersion: UInt64)
    }

    struct ArtifactMetadata {
        let id: String
        let checksum: String
        let promotedAt: Date?
        var deployCount: Int
        var isValidated: Bool
    }

    init(eventLoop: EventLoop, kubeClient: KubernetesClient) {
        self.eventLoop = eventLoop
        self.kubeClient = kubeClient
    }

    // Constant-time comparison of security-sensitive checksum values
    // to avoid timing side-channels (CWE-208).
    private func constantTimeEquals(_ lhs: String, _ rhs: String) -> Bool {
        let lhsBytes = Array(lhs.utf8)
        let rhsBytes = Array(rhs.utf8)
        // Compare lengths without early exit affecting the byte loop.
        var diff: UInt8 = lhsBytes.count == rhsBytes.count ? 0 : 1
        let maxCount = max(lhsBytes.count, rhsBytes.count)
        if maxCount == 0 {
            return diff == 0
        }
        for i in 0..<maxCount {
            let a = i < lhsBytes.count ? lhsBytes[i] : 0
            let b = i < rhsBytes.count ? rhsBytes[i] : 0
            diff |= (a ^ b)
        }
        return diff == 0
    }

    // Entry point: promote artifact through pipeline stages
    func promoteArtifact(id: String, checksum: String, completion: @escaping (Result<Void, Error>) -> Void) {
        eventLoop.execute {
            guard self.deploymentState == .idle else {
                completion(.failure(PipelineError.busyState(self.deploymentState)))
                return
            }

            self.deploymentState = .promoting(artifactId: id)
            self.stateVersion += 1

            let metadata = ArtifactMetadata(
                id: id, checksum: checksum, promotedAt: Date(),
                deployCount: 0, isValidated: false
            )
            self.artifactRegistry[id] = metadata

            // Validate artifact integrity before deployment
            self.validateAndDeploy(artifactId: id, expectedChecksum: checksum, completion: completion)
        }
    }

    private func validateAndDeploy(artifactId: String, expectedChecksum: String, completion: @escaping (Result<Void, Error>) -> Void) {
        // Simulate async validation (e.g., pulling from registry, verifying signature)
        kubeClient.fetchArtifactChecksum(artifactId: artifactId) { [weak self] result in
            guard let self = self else { return }

            switch result {
            case .success(let remoteChecksum):
                guard self.constantTimeEquals(remoteChecksum, expectedChecksum) else {
                    self.handleValidationFailure(artifactId: artifactId, completion: completion)
                    return
                }
                self.artifactRegistry[artifactId]?.isValidated = true
                self.beginDeployment(artifactId: artifactId, completion: completion)

            case .failure(let error):
                self.handleValidationFailure(artifactId: artifactId, completion: completion)
            }
        }
    }

    private func beginDeployment(artifactId: String, completion: @escaping (Result<Void, Error>) -> Void) {
        guard self.deploymentState == .promoting(artifactId: artifactId) else {
            completion(.failure(PipelineError.stateCorruption))
            return
        }

        self.deploymentState = .deploying(artifactId: artifactId)
        let capturedVersion = self.stateVersion

        // Apply Kubernetes deployment manifest
        kubeClient.applyDeployment(artifactId: artifactId) { [weak self] result in
            guard let self = self else { return }

            switch result {
            case .success:
                self.finalizeDeployment(artifactId: artifactId, atVersion: capturedVersion, completion: completion)
            case .failure(let error):
                self.initiateRollback(fromVersion: capturedVersion, reason: error, completion: completion)
            }
        }
    }

    // CRITICAL: State finalization with version check
    private func finalizeDeployment(artifactId: String, atVersion: UInt64, completion: @escaping (Result<Void, Error>) -> Void) {
        // Version check occurs BEFORE processing callbacks to prevent reentrancy
        guard self.stateVersion == atVersion else {
            completion(.failure(PipelineError.stateCorruption))
            return
        }

        // Set reentrancy guard before processing callbacks
        self.isProcessingCallbacks = true
        self.processPendingCallbacks(forArtifact: artifactId)
        self.isProcessingCallbacks = false

        self.artifactRegistry[artifactId]?.deployCount += 1
        self.deploymentState = .idle
        self.stateVersion += 1
        completion(.success(()))
    }

    // Webhook handler - can be triggered by k8s admission controller during deployment
    func handleWebhook(artifactId: String, action: WebhookAction, completion: @escaping (Result<Void, Error>) -> Void) {
        // Reject reentrant webhook calls during callback processing
        guard !isProcessingCallbacks else {
            completion(.failure(PipelineError.stateCorruption))
            return
        }

        // Queue callback for processing during finalization
        pendingCallbacks.append((artifactId, completion))

        // Webhooks during deployment are queued only - no state mutation allowed
        if case .deploying(let currentArtifact) = self.deploymentState, currentArtifact == artifactId {
            if action == .forcePromote {
                // Log the attempt but do NOT mutate state during active deployment
                // State transitions only happen through the proper pipeline flow
                return
            }
        }
    }

    private func processPendingCallbacks(forArtifact artifactId: String) {
        let callbacks = pendingCallbacks.filter { $0.0 == artifactId }
        pendingCallbacks.removeAll { $0.0 == artifactId }

        for (_, callback) in callbacks {
            callback(.success(()))
        }
    }

    private func handleValidationFailure(artifactId: String, completion: @escaping (Result<Void, Error>) -> Void) {
        self.artifactRegistry.removeValue(forKey: artifactId)
        self.deploymentState = .idle
        completion(.failure(PipelineError.validationFailed))
    }

    private func initiateRollback(fromVersion: UInt64, reason: Error, completion: @escaping (Result<Void, Error>) -> Void) {
        self.deploymentState = .rollingBack(fromVersion: fromVersion)
        kubeClient.rollback(toVersion: fromVersion) { [weak self] _ in
            self?.deploymentState = .idle
            completion(.failure(reason))
        }
    }
}

enum WebhookAction: Equatable {
    case forcePromote
    case cancel
    case notify
}

enum PipelineError: Error {
    case busyState(PipelineController.DeploymentState)
    case stateCorruption
    case validationFailed
    case rollbackFailed
}

protocol KubernetesClient {
    func fetchArtifactChecksum(artifactId: String, completion: @escaping (Result<String, Error>) -> Void)
    func applyDeployment(artifactId: String, completion: @escaping (Result<Void, Error>) -> Void)
    func rollback(toVersion: UInt64, completion: @escaping (Result<Void, Error>) -> Void)
}
